        return new EqualsBuilder()
            .setExcludeFields(excludeFields)
            .setReflectUpToClass(reflectUpToClass)
            .setTestTransients(testTransients)
            .setTestRecursive(testRecursive)
            .reflectionAppend(lhs, rhs)
