            this.limit = limit;
            return this;
        }

        /**
         * Sets the time period.
         *
         * @param period The time period.
         * @return {@code this} instance.
         */
        public Builder setPeriod(final long period) {
            this.period = period;
            return this;
        }

        /**
         * Sets the executor service.
         *
         * @param service The executor service.
         * @return {@code this} instance.
         */
